INSERT INTO `CopSahBible2_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, '[ⲁⲁⲃⲣⲁϩⲁⲙ ⲇⲉ ⲥⲱ]ⲧⲙ ⲉⲉⲫ[ⲣⲱⲛ ⲁϥⲧⲛⲛⲟⲟⲩ ⲙⲡϩ]ⲁⲧ [...');
