INSERT INTO `CopSahBible2_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'ⲁϥⲥⲱⲧⲙ ⲇⲉ ⲛϭⲓ ⲡⲗⲁⲟⲥ ⲉⲡⲉⲓϣⲁϫⲉ ⲉⲧⲛⲁϣⲧ ⲁⲩⲣϩⲏⲃⲉ');
