INSERT INTO `CopSahBible2_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'ⲁⲩⲱ ⲡϫⲟⲉⲓⲥ ⲁϥϣⲁϫⲉ ⲛⲛⲁϩⲣⲙ ⲙⲱⲩⲥⲏⲥ ⲉϥϫⲱ ⲙⲙⲟⲥ');
