INSERT INTO `CopSahBible2_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, 'ϫⲉ ⲡⲁⲓ ⲡⲉ ⲡⲣⲁⲛ ⲛⲛⲣⲱⲙⲉ ⲉⲧⲛⲁⲕⲗⲏⲣⲟⲛⲟⲙⲉⲓ ⲙⲡⲕⲁϩ ⲉⲗⲉⲁⲍⲁⲣ ⲡⲟⲩⲏⲏⲃ ⲙⲛ ⲓⲏⲥⲟⲩ ⲡϣⲏⲣⲉ ⲛⲛⲁⲩⲏ');
INSERT INTO `CopSahBible2_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'ⲁⲩϣ ⲧⲉⲧⲛⲉϫⲓ ⲛⲟⲩⲁⲣⲭⲱⲛ ⲕⲁⲧⲁ ⲫⲩⲗⲏ ⲉⲧⲣⲉⲧⲉⲧⲛⲕⲗⲏⲣⲟⲛⲟⲙⲉⲓ ⲙⲡⲕⲁϩ');
