INSERT INTO `CopSahBible2_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'ⲁⲩⲱ ⲕⲉⲫⲁⲣⲁⲁ ⲁⲩⲱ ⲕⲁⲫⲁⲛ ⲁⲩⲱ ⲛⲁⲕⲁⲛ ⲁⲩⲱ ⲕⲉⲣⲥⲏⲁ ⲁⲩⲱ ⲥⲉⲗⲁⲥⲉⲕ');
