INSERT INTO `CopSahBible2_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 46, 18, 'ⲁϥⲟⲩⲱϣϥ ⲛⲛⲟϭ ⲛⲧⲩⲣⲁⲛⲛⲟⲥ ⲁⲩⲱ ⲛⲁⲣⲭⲱⲛ ⲧⲏⲣⲟⲩ ⲛⲛⲉⲫⲩⲗⲓⲥⲧⲓⲉⲓⲙ');
