INSERT INTO `CopSahBible2_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 18, 1, 'ⲟⲩⲟⲓ ⲛⲛⲧⲛϩ ⲛⲛⲉϫⲏⲩ ⲙⲡⲕⲁϩ ⲉⲧϩⲓ ⲡⲉⲕⲣⲟ ⲛⲛⲉⲓⲉⲣⲱⲟⲩ ⲛⲛⲉϭⲟⲟϣ');
